--
-- Name: states states_pkey; Type: CONSTRAINT; Schema: public; Owner: -
--

ALTER TABLE ONLY public.states
    ADD CONSTRAINT states_pkey PRIMARY KEY (id);


--
-- Name: states_country_id_idx; Type: INDEX; Schema: public; Owner: -
--

CREATE INDEX states_country_id_idx ON public.states USING btree (country_id);


--
-- Name: states states_country_id_fkey; Type: FK CONSTRAINT; Schema: public; Owner: -
--

ALTER TABLE ONLY public.states
    ADD CONSTRAINT states_country_id_fkey FOREIGN KEY (country_id) REFERENCES public.countries(id);

--
-- Name: counties; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.counties
(
    id           bigint                 NOT NULL,
    name         character varying(255) NOT NULL,
    state_id     bigint                 NOT NULL,
    state_code   character varying(255) NOT NULL,
    country_id   bigint                 NOT NULL,
    country_code character(2)           NOT NULL,
    type         character varying(191),
    type_local   character varying(191),
    level        integer,
    parent_id    bigint,
    latitude     numeric(10, 8)         NOT NULL,
    longitude    numeric(11, 8)         NOT NULL,
    native       character varying(255),
    population   bigint,
    timezone     character varying(255),
    translations text,
    created_at   timestamp without time zone DEFAULT '2014-01-01 12:01:01'::timestamp without time zone NOT NULL,
    updated_at   timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    flag         smallint DEFAULT 1     NOT NULL,
    "wikiDataId" character varying(255)
);


--
-- Name: COLUMN counties.timezone; Type: COMMENT; Schema: public; Owner: -
--

COMMENT
ON COLUMN public.counties.timezone IS 'IANA timezone identifier (e.g., America/New_York)';


--
-- Name: COLUMN counties."wikiDataId"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT
ON COLUMN public.counties."wikiDataId" IS 'Rapid API GeoDB Cities';


--
-- Name: counties_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.counties ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.counties_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


